-- ============================================================
-- Seed: Portsmouth trades from Google Maps CSV
-- Run this AFTER migration 20260509000001_create_seeded_trades
-- Idempotent: ON CONFLICT (company_name, postcode) DO NOTHING
-- ============================================================

ON CONFLICT (company_name, postcode) DO NOTHING;

DO $$ BEGIN
  RAISE NOTICE '✓ Portsmouth trades seeded — % rows inserted', (SELECT COUNT(*) FROM public.seeded_trades);
END $$;
